// File: \Services\PhotoatomicDataService.cs
using Panex.Models;
using System.Collections.Generic;
using System.IO;
using System.Linq;

namespace Panex.Services;

public class PhotoatomicDataService : IPhotoatomicDataService
{
    public void LoadCrossSections(IEnumerable<Element> elements, string rootPath)
    {
        // Target the new single file generated by the Python script
        string filePath = Path.Combine(rootPath, "epdl_2025_xs.csv");
        if (!File.Exists(filePath)) return;

        // Temporary structure to group the flat CSV rows before creating objects
        // Structure: Z -> (C, S, X) -> (Energies, CrossSections)
        var parsedData = new Dictionary<int, Dictionary<(int C, int S, int X), (List<double> E, List<double> Xs)>>();

        // Stream the file line-by-line to prevent massive RAM spikes
        foreach (var line in File.ReadLines(filePath).Skip(1))
        {
            if (string.IsNullOrWhiteSpace(line)) continue;

            var parts = line.Split(',');
            if (parts.Length < 6) continue;

            if (int.TryParse(parts[0], out int z) &&
                int.TryParse(parts[1], out int c) &&
                int.TryParse(parts[2], out int s) &&
                int.TryParse(parts[3], out int x) &&
                double.TryParse(parts[4], System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out double energy) &&
                double.TryParse(parts[5], System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out double crossSection))
            {
                if (!parsedData.ContainsKey(z))
                    parsedData[z] = new Dictionary<(int C, int S, int X), (List<double>, List<double>)>();

                var key = (c, s, x);
                if (!parsedData[z].ContainsKey(key))
                    parsedData[z][key] = (new List<double>(), new List<double>());

                parsedData[z][key].E.Add(energy);
                parsedData[z][key].Xs.Add(crossSection);
            }
        }

        // Map the grouped data back to the actual Panex Element models
        foreach (var element in elements)
        {
            var curves = new List<CrossSectionCurve>();

            if (parsedData.TryGetValue(element.Z, out var elementData))
            {
                foreach (var kvp in elementData)
                {
                    int c = kvp.Key.C;
                    int s = kvp.Key.S;
                    int x = kvp.Key.X;
                    var energies = kvp.Value.E.ToArray();
                    var crossSections = kvp.Value.Xs.ToArray();

                    curves.Add(new CrossSectionCurve(c, s, x, energies, crossSections));
                }
            }

            element.PhotoatomicData = curves;
        }
    }
}